export async function remoteBranchExists(
  projectRoot: string,
  branchName: string,
  remoteName = "origin",
): Promise<boolean> {
  try {
    const { stdout } = await runGitAsync(projectRoot, [
      "ls-remote",
      "--heads",
      remoteName,
      branchName,
    ]);
    return stdout.trim().length > 0;
  } catch {
    return false;
  }
}

